27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
49	            message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date", columnDefinition = "DATE")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "household_id")
62	    private String householdId;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
68	    private Set<Pet> pets;
69	
70	    public String getAddress() {
71	        return this.address;
72	    }
73	
74	    public void setAddress(String address) {
75	        this.address = address;
76	    }
77	
78	    public String getCity() {
79	        return this.city;
80	    }
81	
82	    public void setCity(String city) {
83	        this.city = city;
84	    }
85	
86	    public String getTelephone() {
87	        return this.telephone;
88	    }
89	
90	    public void setTelephone(String telephone) {
91	        this.telephone = telephone;
92	    }
93	
94	    public String getEmail() {
95	        return this.email;
96	    }
97	
98	    public void setEmail(String email) {
99	        this.email = email;
100	    }
101	
102	    public LocalDate getRegistrationDate() {
103	        return this.registrationDate;
104	    }
105	
106	    public void setRegistrationDate(LocalDate registrationDate) {
107	        this.registrationDate = registrationDate;
108	    }
109	
110	    public String getCustomerCode() {
111	        return this.customerCode;
112	    }
113	
114	    public void setCustomerCode(String customerCode) {
115	        this.customerCode = customerCode;
116	    }
117	
118	    public String getHouseholdId() {
119	        return this.householdId;
120	    }
121	
122	    public void setHouseholdId(String householdId) {
123	        this.householdId = householdId;
124	    }
125	
126	    public Integer getNamesakeCount() {
127	        return this.namesakeCount;
128	    }
129	
130	    public void setNamesakeCount(Integer namesakeCount) {
131	        this.namesakeCount = namesakeCount;
132	    }
133	
134	    protected Set<Pet> getPetsInternal() {
135	        if (this.pets == null) {
136	            this.pets = new HashSet<>();
137	        }
138	        return this.pets;
139	    }
140	
141	    protected void setPetsInternal(Set<Pet> pets) {
142	        this.pets = pets;
143	    }
144	
145	    public List<Pet> getPets() {
146	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
147	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
148	        return Collections.unmodifiableList(sortedPets);
149	    }
150	
151	    public void setPets(List<Pet> pets) {
152	        this.pets = new HashSet<>(pets);
153	    }
154	
155	    public void addPet(Pet pet) {
156	        getPetsInternal().add(pet);
157	        pet.setOwner(this);
158	    }
159	
160	    /**
161	     * Return the Pet with the given name, or null if none found for this Owner.
162	     *
163	     * @param name to test
164	     * @return true if pet name is already in use
165	     */
166	    public Pet getPet(String name) {
167	        return getPet(name, false);
168	    }
169	
170	    /**
171	     * Return the Pet with the given name, or null if none found for this Owner.
172	     *
173	     * @param name to test
174	     * @return true if pet name is already in use
175	     */
176	    public Pet getPet(String name, boolean ignoreNew) {
177	        name = name.toLowerCase();
178	        for (Pet pet : getPetsInternal()) {
179	            if (!ignoreNew || !pet.isNew()) {
180	                String compName = pet.getName();
181	                compName = compName.toLowerCase();
182	                if (compName.equals(name)) {
183	                    return pet;
184	                }
185	            }
186	        }
187	        return null;
188	    }
189	
190	    public Pet getPet(Integer petId) {
191	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
192	    }
193	
194	    @Override
195	    public String toString() {
196	        return new ToStringCreator(this)
197	
198	            .append("id", this.getId())
199	            .append("new", this.isNew())
200	            .append("lastName", this.getLastName())
201	            .append("firstName", this.getFirstName())
202	            .append("address", this.address)
203	            .append("city", this.city)
204	            .append("telephone", this.telephone)
205	            .append("email", this.email)
206	            .toString();
207	    }
208	}
